"""Documentación pública en README.md."""
import argparse
import html
import json
from pathlib import Path
import shutil
import zipfile
ROOT = Path(__file__).resolve().parents[1]

def pct(value):
    return f'{100 * value:.2f}%'

def crear_informe(experiment, destination, code_zip):
    experiment, destination = (Path(experiment), Path(destination))
    report = json.loads((experiment / 'comparacion_publica.json').read_text(encoding='utf-8'))
    if report.get('protocolo', {}).get('version') != 3 or report['protocolo'].get('gt_concurso_usado') is not False or set(report['test']) != {'1927964', '1953632'}:
        raise ValueError('El informe solo admite el experimento público fijado')
    if destination.exists():
        raise FileExistsError('El informe necesita un destino nuevo')
    with zipfile.ZipFile(code_zip) as archive:
        for name in archive.namelist():
            if name.endswith(('.csv', '.mp4', '.npz', '.ipynb', '.pkl')) or name.startswith(('data/', 'outputs/', '.git/')):
                raise ValueError('El ZIP de revisión no admite datos o resultados por frame')
        if archive.testzip() is not None:
            raise ValueError('ZIP de código corrupto')
    destination.mkdir(parents=True, exist_ok=False)
    decision = report['decision']
    winner = decision['candidata_recomendada']
    model = json.loads((experiment / 'modelo_v3.json').read_text(encoding='utf-8'))
    rows = []
    for game, results in report['test'].items():
        for scenario, values in results['escenarios'].items():
            rows.append([game, 'Original' if scenario == 'original' else 'Estrés', pct(values['v2']['spellF1_condicional']), pct(values['v3']['spellF1_condicional']), pct(values['v2']['acuerdo']), pct(values['v3']['acuerdo'])])
    table_md = '\n'.join(('| ' + ' | '.join(row) + ' |' for row in rows))
    regression = report['regresion_metrica']
    regression_rows = [[s, f"{r['v2']['apoyo']['macroF1_apoyo']:.4f}", f"{r['v3']['apoyo']['macroF1_apoyo']:.4f}", pct(r['v2']['anclas']['acuerdo']), pct(r['v3']['anclas']['acuerdo'])] for s, r in regression.items()]
    regression_md = '\n'.join(('| ' + ' | '.join(row) + ' |' for row in regression_rows))
    ablations = []
    for name in ['v2', 'control', 'duracion', 'paradas', 'paradas_hmm']:
        scores = [r[name]['spellF1_condicional'] for r in report['desarrollo'].values()]
        ablations.append([name, f'{sum(scores) / len(scores):.4f}'])
    ablations_md = '\n'.join(('| ' + ' | '.join(row) + ' |' for row in ablations))
    intro = 'La candidata v3 supera el criterio externo fijado y queda recomendada para revisión del equipo.' if decision['promover_v3'] else 'La candidata v3 no supera todos los criterios externos. Conservamos v2 como recomendada y v3 como experimento reproducible.'
    md = f"# veriana — Revisión de la primera entrega\n\n15 de noviembre de 2026. Documento para el equipo. {intro}\n\n## Qué cambió\n\nAmpliamos el desarrollo de dos a ocho partidos públicos de otros encuentros: dos de Metrica y\nseis de SkillCorner. El control v3 usa {model['control_v3']['referencias']:,} referencias externas\ny nueve características geométricas y temporales. Conservamos la pausa v2 y el tratamiento\nexplícito de observaciones ausentes. Se implementó y comparó un HSMM con edad explícita,\nademás de una extensión de anticipación de paradas. La selección externa escogió\n`{report['variante_congelada']}`. Las variantes descartadas permanecen disponibles en el código.\n\n## Resultado de los partidos reservados\n\n| Partido | Escenario | spell cond. v2 | spell cond. v3 | Acuerdo H/A v2 | Acuerdo H/A v3 |\n|---|---|---:|---:|---:|---:|\n{table_md}\n\nGanancia media de spellF1 condicional: {100 * decision['ganancia_media_spellF1_condicional']:+.2f} puntos\nporcentuales. Este resultado NO es el spellF1 oficial. SkillCorner aporta posesión automática H/A,\nsin D completo. Sus X recortan el dominio y pueden recortar posesiones. Las cifras comparan\nmodelos contra otra convención automática, con solo dos partidos reservados.\n\n## Guardia de regresión en Metrica Game 2\n\n| Escenario | Macro F1 débil v2 | Macro F1 débil v3 | Anclas H/A v2 | Anclas H/A v3 |\n|---|---:|---:|---:|---:|\n{regression_md}\n\nMetrica Game 2 ya se había usado en desarrollo. Sus referencias H/A/D son parciales y débiles,\nno GT completo. No se presenta como otro test ciego ni como puntuación oficial.\n\n## Qué aportó cada componente en desarrollo\n\nMedia de spellF1 condicional en SkillCorner 1925299, original y estrés:\n\n| Variante | Media |\n|---|---:|\n{ablations_md}\n\nSe congelaron la variante y el JSON del modelo antes de evaluar los dos partidos reservados.\nLa calibración binaria del control eligió temperatura {model['temperatura_control']:g} por log-loss\nen desarrollo. No calibra la probabilidad de acierto H/A/D del modelo temporal.\n\n## Cómo funciona\n\n1. **Preprocesamiento:** validar frames y equipos, convertir a metros, respetar mitades y NaN.\n2. **Características:** distancias, velocidad relativa, continuidad, apoyo, aproximación,\n   acceso cinemático a 0,4/0,8 s y contexto temporal. Un toque cercano no fija el dueño.\n3. **Control y parada:** control H/A aprendido con otros partidos y pausa sustentada por\n   movimiento más evidencia física. Balón ausente no significa juego detenido.\n4. **Modelo temporal:** inferencia offline con observaciones anteriores y posteriores,\n   penalización de cambios y abstención X. La variante elegida usa HMM.\n5. **Entrega:** CSV completo validado y reproducción idéntica desde código extraído.\n\n## Fuentes y partición\n\n| Fuente | Uso | Precaución |\n|---|---|---|\n| Metrica Game 1 | Control y pausa | Eventos puntuales y referencias débiles |\n| Metrica Game 2 | Guardia de regresión | Ya usado en desarrollo |\n| SkillCorner 1874553, 1886347, 1899585 | Entrenar control y estudiar duración | Etiquetas automáticas |\n| SkillCorner 1925299 | Elegir variante y temperatura | Solo desarrollo |\n| SkillCorner 1927964, 1953632 | Evaluación reservada, una vez | Solo dos partidos, misma liga |\n| Partido del concurso | Inferencia local | Sin entrenamiento ni anotación manual |\n\nSkillCorner se procesa a 10 fps nativos y descarta posiciones extrapoladas como observaciones.\n`possession`, fases y eventos de referencia no entran al modelo. Null sigue siendo X.\nLos archivos públicos están fijados por commit y verificados por hashes, incluido Git LFS.\n\nTambién revisamos StatsBomb Open Data y SoccerNet GSR. Los eventos y freeze-frames de StatsBomb\nno reemplazan tracking continuo. SoccerNet GSR es una vía para reconstrucción visual de jugadores,\npero incorporarlo exige otro desarrollo y evaluación. No se añadieron datos humanos del partido\ndel concurso desde ninguna de esas fuentes.\n\n## Las métricas del reto\n\nMacroF1 promedia el F1 de H, A y D por frame. X en un frame evaluable cuenta como fallo.\nSpellF1 trata cada posesión H/A completa como un objeto: empareja posesiones del mismo equipo\npor IoU temporal y promedia F1 en 0,3/0,4/0,5/0,6/0,7. Antes rellena los X predichos con la última\netiqueta dentro de la mitad. SpellF1 decide el ranking. Los ejemplos sintéticos y la explicación\nexacta se conservan en `docs/02_METRICAS.md` del repositorio.\n\n## Qué revisamos y qué queda fuera de la candidata\n\nEl estrés mezcla oclusiones dependientes de aglomeración/velocidad, huecos largos, saltos,\npérdida de tracklets y cambios de slots. Es reproducible y no usa etiquetas para generar ruido.\nLos tests incluyen cambios rápidos y comprobación exacta de Viterbi/marginales HSMM por enumeración.\n\nEl HSMM y la anticipación adicional de paradas quedaron fuera tras la comparación de desarrollo.\nLa homografía y los contenedores de vídeo cuentan con auditoría local. No implementamos un nuevo\ndetector visual ni sincronización broadcast–táctico en esta iteración. Esas líneas necesitan\nvalidación externa propia antes de cambiar etiquetas. El modelo aún tiene límites en huecos\nlargos, rebotes y posesión estática. La evaluación oficial de todo el partido sigue desconocida.\n\n## Material para el equipo\n\n`INFORME_VERIANA.html` permite presentar este análisis sin conexión. `codigo_publicable.zip`\ncontiene fuentes, pruebas, dependencias fijadas, documentación y el modelo recomendado {winner}.\n`comparacion_publica.json` y `protocolo_previo.json` permiten auditar los experimentos externos.\nEsta carpeta no contiene CSV, vídeos, tracking ni diagnósticos del concurso. No se ha publicado\nni enviado nada. Los artefactos privados quedan en otra carpeta local de entrega.\n\nLa entrega oficial exige CSV, repositorio público y documento técnico. La fecha publicada es\n17 de noviembre de 2026. Preparar este paquete no equivale a publicar o enviar la entrega.\n\n## Referencias primarias\n\n- [Reglas del concurso](https://github.com/metrica-sports/more-than-a-hack-2027/blob/main/RULES.md)\n- [Contrato de entrega](https://github.com/metrica-sports/more-than-a-hack-2027/blob/main/SUBMISSION.md)\n- [Metrica Sports sample-data](https://github.com/metrica-sports/sample-data/tree/e706dd506b360d69d9d123d5b8026e7294b13996)\n- [SkillCorner Open Data y documentación](https://github.com/SkillCorner/opendata/tree/4340d274572876239c154c90bc507a9b3250a656)\n- [Murphy: Hidden semi-Markov models](https://www.cs.ubc.ca/~murphyk/Papers/segment.pdf)\n- [StatsBomb Open Data](https://github.com/statsbomb/open-data)\n- [SoccerNet Game State Reconstruction](https://www.soccer-net.org/tasks/game-state-reconstruction)\n"
    (destination / 'INFORME_VERIANA.md').write_text(md, encoding='utf-8')

    def table(headers, values):
        return '<div class="scroll"><table><thead><tr>' + ''.join(('<th>' + html.escape(h) + '</th>' for h in headers)) + '</tr></thead><tbody>' + ''.join(('<tr>' + ''.join(('<td>' + html.escape(str(c)) + '</td>' for c in r)) + '</tr>' for r in values)) + '</tbody></table></div>'
    test_table = table(['Partido', 'Escenario', 'Spell cond. v2', 'Spell cond. v3', 'H/A v2', 'H/A v3'], rows)
    regression_table = table(['Escenario', 'Macro débil v2', 'Macro débil v3', 'Anclas H/A v2', 'Anclas H/A v3'], regression_rows)
    bars = ''.join((f'<div class="barrow"><span>{html.escape(name)}</span><div class="track"><div class="bar" style="width:{float(value) * 100:.2f}%"></div></div><b>{value}</b></div>' for name, value in ablations))
    page = f"""<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">\n<meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'">\n<title>veriana · Revisión de la primera entrega</title><style>\n*{{box-sizing:border-box}}body{{margin:0;background:#eef2f4;color:#152a36;font:17px/1.6 'Segoe UI',Arial,sans-serif}}header{{background:#102c36;color:#fff;padding:65px max(5vw,calc((100vw - 1140px)/2)) 48px}}h1{{font-size:clamp(36px,5vw,62px);line-height:1.08;max-width:900px;margin:18px 0}}header p{{max-width:780px;color:#d8e6e8}}.eyebrow{{font-size:13px;letter-spacing:2px;text-transform:uppercase;color:#8ff0bd}}nav{{background:white;border-bottom:1px solid #d5dfe3;padding:15px 5vw;display:flex;gap:26px;flex-wrap:wrap}}a{{color:#087754;text-decoration:underline;text-underline-offset:3px}}nav a{{text-decoration:none;font-size:15px}}main{{max-width:1180px;padding:30px 20px 60px;margin:auto}}section{{background:#fff;padding:34px 38px;margin:22px 0;border:1px solid #dce4e7;border-radius:12px}}h2{{font-size:29px;line-height:1.2;margin:0 0 20px}}h3{{font-size:20px;margin:0 0 8px}}p{{max-width:1000px}}.grid{{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}}.stat{{background:#eef8f2;border-radius:8px;padding:22px}}.stat b{{font-size:34px;line-height:1.1;display:block;color:#0a704a}}.stat span{{font-size:14px}}.note{{border-left:4px solid #dcad39;background:#fff9e8;padding:16px 20px;margin-top:22px}}.steps{{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}}.step{{background:#f0f5f6;padding:18px;border-radius:8px}}.step b{{color:#087754}}.step p{{font-size:15px;margin-bottom:0}}.scroll{{overflow-x:auto}}table{{width:100%;border-collapse:collapse;font-size:15px}}th{{background:#e9f1f3;text-align:left}}th,td{{padding:13px 14px;border-bottom:1px solid #d9e3e7;white-space:nowrap}}tr:nth-child(even){{background:#f7fafb}}.barrow{{display:grid;grid-template-columns:140px 1fr 65px;gap:14px;align-items:center;margin:15px 0;font-size:15px}}.track{{height:20px;background:#e8eef1;border-radius:4px}}.bar{{height:100%;background:#15916c;border-radius:4px}}.small{{font-size:14px;color:#4c6572}}.pill{{display:inline-block;background:#d0f4df;color:#134d35;padding:5px 13px;border-radius:30px;font-size:14px}}details{{padding:15px 0;border-bottom:1px solid #e1e7ea}}summary{{font-weight:600;cursor:pointer}}footer{{padding:25px 5vw;background:#102c36;color:#d8e6e8;font-size:14px}}@media(max-width:750px){{section{{padding:25px 20px}}.grid,.steps{{grid-template-columns:1fr}}header{{padding:38px 25px}}.barrow{{grid-template-columns:105px 1fr 55px}}}}@media print{{body{{background:#fff;font-size:11pt}}nav{{display:none}}header{{padding:25px;color:#102c36;background:#fff}}header p{{color:#233}}section{{break-inside:avoid;border:0;padding:20px 0}}main{{padding:0}}h1{{font-size:32pt}}.grid{{grid-template-columns:repeat(3,1fr)}}}}\n</style></head><body><header><div class="eyebrow">More Than a Hack 2027 · Fase 1 · 15 nov 2026</div><h1>Posesión con evidencia<br>para cada transición</h1><p>Revisión técnica de <strong>veriana</strong>. Ocho partidos externos para desarrollar y comprobar la solución, con el partido del concurso reservado para inferencia local.</p><span class="pill">Candidata recomendada: {winner}</span></header>\n<nav><a href="#resumen">Decisión</a><a href="#resultados">Resultados</a><a href="#metodo">Método</a><a href="#fuentes">Fuentes</a><a href="#limites">Límites</a><a href="#archivos">Archivos</a></nav><main>\n<section id="resumen"><h2>Más datos y una comparación por componentes</h2><p>{intro}</p><div class="grid"><div class="stat"><b>8</b><span>partidos externos en dos fuentes</span></div><div class="stat"><b>{model['control_v3']['referencias']:,}</b><span>referencias para el control v3</span></div><div class="stat"><b>{100 * decision['ganancia_media_spellF1_condicional']:+.2f} pp</b><span>spellF1 condicional medio en test externo</span></div></div><div class="note">La puntuación oficial sigue desconocida. Las métricas externas usan referencias parciales y otra convención automática de posesión.</div></section>\n<section id="resultados"><h2>Dos partidos completos reservados antes del ajuste</h2><p>La elección del modelo quedó congelada antes de evaluar estos partidos. Cada fila compara v2 con la misma candidata v3.</p>{test_table}<p class="small">SpellF1 condicional: aplica el emparejamiento oficial solo dentro de regiones H/A conocidas de SkillCorner. Los desconocidos recortan el dominio. No evalúa todas las paradas ni representa el score del concurso.</p><details open><summary>Regresión sobre referencias externas de Metrica</summary><p>Game 2 ya era desarrollo. Macro F1 usa apoyo débil H/A/D. Las anclas H/A son puntos de eventos.</p>{regression_table}</details><details><summary>Ablaciones en el partido de desarrollo</summary><p>Promedio original/estrés. La variante congelada fue <strong>{report['variante_congelada']}</strong>.</p>{bars}<p class="small">El HSMM y la extensión de paradas permanecen en el código para investigación. Esta comparación no justifica activarlos en la candidata elegida.</p></details></section>\n<section id="metodo"><h2>Control, parada y continuidad se resuelven juntos</h2><div class="steps"><div class="step"><b>01 · Preparar</b><h3>Tracking válido</h3><p>Frames, equipos y metros. NaN conserva ausencia. Las mitades reinician el contexto.</p></div><div class="step"><b>02 · Extraer</b><h3>Acceso al balón</h3><p>Distancia, velocidad relativa, apoyo, continuidad y proyección a 0,4/0,8 segundos.</p></div><div class="step"><b>03 · Inferir</b><h3>Control y pausa</h3><p>Regresión simétrica H/A, evidencia física de D y priors débiles de Smart Tagging.</p></div><div class="step"><b>04 · Decodificar</b><h3>Posesiones</h3><p>HMM offline, transiciones sostenidas y X cuando falta evidencia. CSV completo y reproducible.</p></div></div><p>La cercanía aislada no decide posesión. La ausencia del balón no decide D. Las observaciones anteriores y posteriores ayudan durante oclusiones.</p><details><summary>Duración, incertidumbre y pruebas de estrés</summary><p>Implementamos un HSMM con edad explícita y cola geométrica, sin duración mínima dura. Verificamos Viterbi y marginales por enumeración exhaustiva. La comparación de desarrollo mantuvo HMM.</p><p>La calibración binaria eligió temperatura {model['temperatura_control']:g}. Solo se refiere a control H/A con observaciones plausibles. El estrés combina aglomeración, velocidad, huecos largos, saltos y cambios de slots con semilla fija.</p></details></section>\n<section id="fuentes"><h2>Separación por partido y procedencia verificable</h2>{table(['Fuente', 'Entrenamiento', 'Desarrollo', 'Reservado'], [['Metrica', 'Game 1', 'Game 2, regresión', '—'], ['SkillCorner', '1874553 · 1886347 · 1899585', '1925299', '1927964 · 1953632']])}<p>SkillCorner conserva sus 10 fps nativos. Descartamos coordenadas extrapoladas como observaciones. La posesión y las fases del proveedor sirven solo de referencia, nunca como entrada. Un poseedor desconocido permanece X.</p><p class="small">Metrica aporta eventos puntuales y referencias débiles. SkillCorner aporta posesión automática H/A, sin D explícito. Ambos corpus están fijados por commit y hashes. No utilizamos datos humanos de otras fuentes sobre el partido del concurso.</p></section>\n<section><h2>Las dos métricas miran errores diferentes</h2><div class="grid" style="grid-template-columns:1fr 1fr"><div class="step"><h3>MacroF1</h3><p>Promedia F1 de H, A y D por frame. Penaliza los X evaluables. Ayuda a detectar errores de equipo y de juego detenido.</p></div><div class="step"><h3>SpellF1</h3><p>Decide el ranking. Empareja posesiones completas del mismo equipo por IoU temporal. Promedia F1 a cinco umbrales entre 0,3 y 0,7.</p></div></div><p>Antes del emparejamiento, el evaluador rellena X predichos con la última etiqueta de la mitad. Una abstención dentro de una posesión y una abstención durante un cambio tienen costes distintos.</p></section>\n<section id="limites"><h2>Qué podemos defender ante el equipo</h2><p>Existe una comparación externa reproducible, con dos partidos reservados y ablaciones. El control utiliza más referencias de otros encuentros. Las pruebas numéricas comprueban la inferencia temporal y los contratos de datos.</p><p>Las etiquetas automáticas pueden compartir errores con el tracking. Dos partidos de la misma liga no prueban generalización al concurso. No hay una evaluación independiente completa de las paradas.</p><p>La homografía y los vídeos tienen auditoría local. Un nuevo detector visual y la sincronización broadcast–táctico siguen fuera de esta iteración: requieren implementación y validación propias. No prometemos una mejora del score oficial.</p><div class="note">Los cinco minutos oficiales no se usan para entrenar, ajustar o escoger versiones. El bundle y sus diagnósticos siguen locales. No hay anotaciones manuales, publicaciones ni envíos.</div></section>\n<section id="archivos"><h2>Versión para revisar y presentar</h2><p><a href="INFORME_VERIANA.md">Informe completo en Markdown</a> · <a href="codigo_publicable.zip">Código y modelo recomendado</a> · <a href="comparacion_publica.json">Resultados públicos por partido</a> · <a href="protocolo_previo.json">Protocolo fijado</a></p><p>Esta carpeta contiene materiales para el equipo sin datos del concurso. El CSV privado y sus registros están en otra carpeta local de entrega. La entrega oficial requiere CSV, repositorio público y documento técnico.</p><p class="small">Fuentes: <a href="https://github.com/metrica-sports/more-than-a-hack-2027/blob/main/SUBMISSION.md">contrato oficial y fecha de entrega: 17 nov 2026</a>, <a href="https://github.com/metrica-sports/sample-data">Metrica Sports</a>, <a href="https://github.com/SkillCorner/opendata/tree/{report['protocolo']['commits']['skillcorner']}">SkillCorner y PySport</a>, <a href="https://www.cs.ubc.ca/~murphyk/Papers/segment.pdf">HSMM, Murphy</a>. Créditos y licencias incluidos en el código.</p></section>\n</main><footer>veriana · Revisión de Fase 1 · Informe offline, sin recursos de red ni datos restringidos</footer></body></html>"""
    (destination / 'INFORME_VERIANA.html').write_text(page, encoding='utf-8')
    for name in ['comparacion_publica.json', 'protocolo_previo.json', 'seleccion_antes_test.json']:
        shutil.copyfile(experiment / name, destination / name)
    shutil.copyfile(code_zip, destination / 'codigo_publicable.zip')
    with zipfile.ZipFile(destination / 'veriana_revision_equipo.zip', 'x', compression=zipfile.ZIP_DEFLATED) as archive:
        for path in sorted(destination.iterdir()):
            if path.name != 'veriana_revision_equipo.zip':
                archive.write(path, path.name)
    print('Informe del equipo creado únicamente con fuentes públicas externas')
    return destination
if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--experimento', default=str(ROOT / 'outputs/experimento_v3_01'))
    parser.add_argument('--salida', required=True)
    parser.add_argument('--codigo', required=True)
    args = parser.parse_args()
    crear_informe(args.experimento, args.salida, args.codigo)
